SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

CREATE TABLE roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,slug VARCHAR(80) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE permissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE role_permissions (role_id BIGINT UNSIGNED NOT NULL,permission_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE branches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,code VARCHAR(20) NOT NULL UNIQUE,address VARCHAR(255),phone VARCHAR(40),status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE brands (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,code VARCHAR(20) NOT NULL UNIQUE,color VARCHAR(20) DEFAULT '#6d5dfc',status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,role_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NULL,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(40),password_hash VARCHAR(255) NOT NULL,avatar VARCHAR(255),status ENUM('active','inactive','locked') DEFAULT 'active',force_password_change TINYINT(1) DEFAULT 1,last_login_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,FOREIGN KEY(role_id) REFERENCES roles(id),FOREIGN KEY(branch_id) REFERENCES branches(id)) ENGINE=InnoDB;
CREATE TABLE webauthn_credentials (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,credential_id VARCHAR(512) NOT NULL UNIQUE,public_key_pem TEXT NOT NULL,sign_count BIGINT UNSIGNED NOT NULL DEFAULT 0,transports JSON NULL,device_name VARCHAR(100) NOT NULL DEFAULT 'Fingerprint / Face ID',last_used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,revoked_at DATETIME NULL,INDEX(user_id,revoked_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE remember_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,selector CHAR(32) NOT NULL UNIQUE,token_hash CHAR(64) NOT NULL,expires_at DATETIME NOT NULL,last_used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,expires_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,description TEXT,sort_order INT DEFAULT 0,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE units (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(50) NOT NULL,symbol VARCHAR(20) NOT NULL,status ENUM('active','inactive') DEFAULT 'active') ENGINE=InnoDB;
CREATE TABLE products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED,unit_id BIGINT UNSIGNED NOT NULL,default_brand_id BIGINT UNSIGNED,sku VARCHAR(80) NOT NULL UNIQUE,barcode VARCHAR(100),name VARCHAR(160) NOT NULL,description TEXT,cost_price DECIMAL(14,2) DEFAULT 0,selling_price DECIMAL(14,2) DEFAULT 0,minimum_stock DECIMAL(14,3) DEFAULT 0,image VARCHAR(255),status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,INDEX(name),INDEX(barcode),FOREIGN KEY(category_id) REFERENCES categories(id),FOREIGN KEY(unit_id) REFERENCES units(id),FOREIGN KEY(default_brand_id) REFERENCES brands(id)) ENGINE=InnoDB;
CREATE TABLE suppliers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,contact_person VARCHAR(120),phone VARCHAR(40),email VARCHAR(190),address TEXT,tax_number VARCHAR(80),notes TEXT,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE employees (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,branch_id BIGINT UNSIGNED,employee_no VARCHAR(40) NOT NULL UNIQUE,name VARCHAR(140) NOT NULL,phone VARCHAR(40),email VARCHAR(190),position VARCHAR(100),joining_date DATE,photo VARCHAR(255),status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,FOREIGN KEY(branch_id) REFERENCES branches(id)) ENGINE=InnoDB;

CREATE TABLE sales (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference_no VARCHAR(40) NOT NULL UNIQUE,sale_date DATE NOT NULL,branch_id BIGINT UNSIGNED NOT NULL,brand_id BIGINT UNSIGNED NOT NULL,subtotal DECIMAL(14,2) NOT NULL DEFAULT 0,total_amount DECIMAL(14,2) NOT NULL DEFAULT 0,cash_amount DECIMAL(14,2) NOT NULL DEFAULT 0,card_amount DECIMAL(14,2) NOT NULL DEFAULT 0,talabat_amount DECIMAL(14,2) NOT NULL DEFAULT 0,keeta_amount DECIMAL(14,2) NOT NULL DEFAULT 0,snoonu_amount DECIMAL(14,2) NOT NULL DEFAULT 0,notes TEXT,status ENUM('draft','completed','cancelled') DEFAULT 'completed',created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,UNIQUE KEY uq_daily_sales(sale_date,branch_id,brand_id),INDEX(sale_date,branch_id,brand_id),FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(brand_id) REFERENCES brands(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE sale_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sale_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(14,3) NOT NULL,unit_price DECIMAL(14,2) NOT NULL,line_total DECIMAL(14,2) NOT NULL,FOREIGN KEY(sale_id) REFERENCES sales(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
CREATE TABLE stock_receivings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference_no VARCHAR(40) NOT NULL UNIQUE,received_date DATE NOT NULL,branch_id BIGINT UNSIGNED NOT NULL,brand_id BIGINT UNSIGNED NOT NULL,supplier_id BIGINT UNSIGNED,invoice_no VARCHAR(100),total_cost DECIMAL(14,2) DEFAULT 0,attachment VARCHAR(255),notes TEXT,status ENUM('draft','completed','cancelled') DEFAULT 'completed',created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,INDEX(received_date,branch_id,brand_id),FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(brand_id) REFERENCES brands(id),FOREIGN KEY(supplier_id) REFERENCES suppliers(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE stock_receiving_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,receiving_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(14,3) NOT NULL,unit_cost DECIMAL(14,2) NOT NULL,line_total DECIMAL(14,2) NOT NULL,FOREIGN KEY(receiving_id) REFERENCES stock_receivings(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
CREATE TABLE stock_usages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference_no VARCHAR(40) NOT NULL UNIQUE,usage_date DATE NOT NULL,branch_id BIGINT UNSIGNED NOT NULL,brand_id BIGINT UNSIGNED NOT NULL,department VARCHAR(100),reason VARCHAR(180),notes TEXT,status ENUM('draft','pending','approved','cancelled') DEFAULT 'approved',created_by BIGINT UNSIGNED NOT NULL,approved_by BIGINT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,INDEX(usage_date,branch_id,brand_id),FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(brand_id) REFERENCES brands(id),FOREIGN KEY(created_by) REFERENCES users(id),FOREIGN KEY(approved_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE stock_usage_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usage_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(14,3) NOT NULL,FOREIGN KEY(usage_id) REFERENCES stock_usages(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
CREATE TABLE wastages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference_no VARCHAR(40) NOT NULL UNIQUE,wastage_date DATE NOT NULL,branch_id BIGINT UNSIGNED NOT NULL,brand_id BIGINT UNSIGNED NOT NULL,reason VARCHAR(100) NOT NULL,cost_impact DECIMAL(14,2) DEFAULT 0,evidence VARCHAR(255),notes TEXT,status ENUM('draft','pending','approved','cancelled') DEFAULT 'approved',created_by BIGINT UNSIGNED NOT NULL,approved_by BIGINT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,INDEX(wastage_date,branch_id,brand_id),FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(brand_id) REFERENCES brands(id),FOREIGN KEY(created_by) REFERENCES users(id),FOREIGN KEY(approved_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE wastage_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,wastage_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(14,3) NOT NULL,unit_cost DECIMAL(14,2) DEFAULT 0,FOREIGN KEY(wastage_id) REFERENCES wastages(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
CREATE TABLE stock_transfers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference_no VARCHAR(40) NOT NULL UNIQUE,transfer_date DATE NOT NULL,from_branch_id BIGINT UNSIGNED NOT NULL,to_branch_id BIGINT UNSIGNED NOT NULL,brand_id BIGINT UNSIGNED NOT NULL,status ENUM('draft','pending','approved','in_transit','received','cancelled') DEFAULT 'received',notes TEXT,requested_by BIGINT UNSIGNED NOT NULL,approved_by BIGINT UNSIGNED,received_by BIGINT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,FOREIGN KEY(from_branch_id) REFERENCES branches(id),FOREIGN KEY(to_branch_id) REFERENCES branches(id),FOREIGN KEY(brand_id) REFERENCES brands(id),FOREIGN KEY(requested_by) REFERENCES users(id),FOREIGN KEY(approved_by) REFERENCES users(id),FOREIGN KEY(received_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE stock_transfer_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,transfer_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(14,3) NOT NULL,FOREIGN KEY(transfer_id) REFERENCES stock_transfers(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
CREATE TABLE stock_adjustments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference_no VARCHAR(40) NOT NULL UNIQUE,adjustment_date DATE NOT NULL,branch_id BIGINT UNSIGNED NOT NULL,brand_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,direction ENUM('increase','decrease') NOT NULL,quantity DECIMAL(14,3) NOT NULL,reason VARCHAR(190) NOT NULL,notes TEXT,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(brand_id) REFERENCES brands(id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE inventory_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NOT NULL,brand_id BIGINT UNSIGNED NOT NULL,transaction_type ENUM('opening','receiving','sale','usage','wastage','transfer_out','transfer_in','adjustment_in','adjustment_out','return','reversal') NOT NULL,reference_type VARCHAR(50) NOT NULL,reference_id BIGINT UNSIGNED NOT NULL,reference_no VARCHAR(50) NOT NULL,quantity_in DECIMAL(14,3) DEFAULT 0,quantity_out DECIMAL(14,3) DEFAULT 0,balance DECIMAL(14,3) NOT NULL,user_id BIGINT UNSIGNED,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(product_id,branch_id,brand_id,created_at),INDEX(reference_type,reference_id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(brand_id) REFERENCES brands(id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;

CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,type VARCHAR(50) NOT NULL,title VARCHAR(160) NOT NULL,message TEXT NOT NULL,link VARCHAR(255),read_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,read_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(80) NOT NULL,module VARCHAR(100) NOT NULL,record_id BIGINT UNSIGNED NULL,old_values JSON NULL,new_values JSON NULL,ip_address VARCHAR(45),user_agent VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(module,record_id),INDEX(user_id,created_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190),ip_address VARCHAR(45),success TINYINT(1) DEFAULT 0,user_agent VARCHAR(500),attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(ip_address,attempted_at)) ENGINE=InnoDB;
CREATE TABLE password_resets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash VARCHAR(255) NOT NULL,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE system_settings (setting_key VARCHAR(120) PRIMARY KEY,setting_value TEXT,updated_by BIGINT UNSIGNED NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE user_preferences (user_id BIGINT UNSIGNED NOT NULL,preference_key VARCHAR(100) NOT NULL,preference_value TEXT,PRIMARY KEY(user_id,preference_key),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;

